19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE = 0.1;
21	
22	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
23	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
24	
25	const BASE_PREMIUMS: Record<string, number> = {
26	  sword: 100,
27	  amulet: 60,
28	  staff: 80,
29	  potion: 40,
30	};
31	
32	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
33	
34	const quotePremium = (step: QuoteStep): number => {
35	  const policyBasePremium = step.items.reduce(
36	    (sum, item) => sum + itemBasePremium(item),
37	    0,
38	  );
39	  const policyPremium = policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE);
40	
41	  return roundUp(policyPremium + PROCESSING_FEE);
42	};
43	
44	export const runScenario = (scenario: Scenario): ScenarioResults => ({
45	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
46	});
